-- ============================================================================
-- scripts/build09_hashes.sql  (build 09, check 5)
-- Row count and two content hashes of every object of the rebuilt lane
-- INVITED_CLUBS: staging and transformation tables, its classification rows and
-- its slice of the six SEM_AI tables.
--   content_hash  full content (RUN_ID, or LAST_SEEN_RUN_ID, excluded)
--   rest_hash     content excluding every column this build may change:
--                 ACCOUNT_DESC, IS_SUBTOTAL, SUBTOTAL_SOURCE, UNKNOWN_REASON,
--                 H1-H5, P_L_SECTION, NORMAL_BALANCE, VALUE_SIGN, VALUE,
--                 METRIC_UNIT, AGGREGATION_TYPE, SEED_SOURCE
-- Taken before the first redeploy. 19 objects.
-- ============================================================================
select 'SEMANTIC.SEM_AI_BALANCE_SHEET INVITED_CLUBS' as obj, count(*) as row_count, hash_agg(object_delete(object_construct_keep_null(*), 'RUN_ID')) as content_hash, hash_agg(object_delete(object_construct_keep_null(*), 'RUN_ID', 'LAST_SEEN_RUN_ID', 'ACCOUNT_DESC', 'IS_SUBTOTAL', 'SUBTOTAL_SOURCE', 'UNKNOWN_REASON', 'H1', 'H2', 'H3', 'H4', 'H5', 'P_L_SECTION', 'NORMAL_BALANCE', 'VALUE_SIGN', 'VALUE', 'METRIC_UNIT', 'AGGREGATION_TYPE', 'SEED_SOURCE')) as rest_hash from DEV_G2M_AI.SEMANTIC.SEM_AI_BALANCE_SHEET where source_lane = 'INVITED_CLUBS'
